const DIFFICULTY_COLOR = {
  Easy: "#5fae6e",
  Moderate: "#e0a83e",
  Hard: "#e0604e",
};

// How much wider the background is than the card. 130% means there's a
// modest amount of extra image width hidden, available to pan through as
// the card moves across the viewport.
const BG_SIZE_PERCENT = 130;

function Card({
  trail,
  viewportWidth,
  cardLeft,
  cardWidth,
  cardHeight,
  onSelect,
}) {
  const center = cardLeft + cardWidth / 2;
  const fraction =
    viewportWidth > 0 ? Math.min(1, Math.max(0, center / viewportWidth)) : 0.5;

  return (
    <div
      onClick={() => onSelect(trail)}
      role="button"
      tabIndex={0}
      style={{
        flex: `0 0 ${cardWidth}px`,
        height: cardHeight,
        borderRadius: 16,
        overflow: "hidden",
        position: "relative",
        scrollSnapAlign: "start",
        boxShadow: "0 8px 20px -10px rgba(0,0,0,0.5)",
        background: "#1a1c20",
        cursor: "pointer",
      }}>
      <div
        style={{
          position: "absolute",
          inset: 0,
          backgroundImage: `url(${trail.img})`,
          backgroundSize: `${BG_SIZE_PERCENT}% 100%`,
          backgroundPosition: `${fraction * 100}% center`,
          backgroundRepeat: "no-repeat",
          willChange: "background-position",
        }}
      />
      <div
        style={{
          position: "absolute",
          inset: 0,
          background:
            "linear-gradient(180deg, rgba(0,0,0,0) 45%, rgba(0,0,0,0.7) 100%)",
        }}
      />
      <div
        style={{
          position: "absolute",
          top: 8,
          left: 8,
          fontSize: 10,
          fontWeight: 700,
          color: "#fff",
          background: DIFFICULTY_COLOR[trail.difficulty],
          borderRadius: 6,
          padding: "2px 6px",
          textShadow: "0 1px 2px rgba(0,0,0,0.3)",
        }}>
        {trail.difficulty}
      </div>
      <div
        style={{
          position: "absolute",
          left: 10,
          right: 10,
          bottom: 8,
          color: "#fff",
        }}>
        <div
          style={{
            fontSize: 13,
            fontWeight: 700,
            lineHeight: 1.2,
            textShadow: "0 1px 4px rgba(0,0,0,0.6)",
          }}>
          {trail.name}
        </div>
        <div
          style={{
            fontSize: 11,
            opacity: 0.85,
            marginTop: 2,
            textShadow: "0 1px 4px rgba(0,0,0,0.6)",
          }}>
          {trail.distance}
        </div>
      </div>
    </div>
  );
}

function Row({
  title,
  subtitle,
  trails,
  cardWidth = 120,
  cardHeight = 162,
  onSelect,
}) {
  const scrollRef = useRef(null);
  const [scrollX, setScrollX] = useState(0);
  const [viewportWidth, setViewportWidth] = useState(0);
  const gap = 10;

  useEffect(() => {
    const el = scrollRef.current;
    setViewportWidth(el.clientWidth);

    let raf;
    const onScroll = () => {
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(() => setScrollX(el.scrollLeft));
    };
    const onResize = () => setViewportWidth(el.clientWidth);

    el.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onResize);
    return () => {
      el.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onResize);
      cancelAnimationFrame(raf);
    };
  }, []);

  return (
    <div style={{ marginBottom: 28 }}>
      <div style={{ padding: "0 20px", marginBottom: 10 }}>
        <div style={{ color: "#fff", fontSize: 16, fontWeight: 700 }}>
          {title}
        </div>
        {subtitle && (
          <div style={{ color: "#8a8d96", fontSize: 12, marginTop: 2 }}>
            {subtitle}
          </div>
        )}
      </div>
      <div
        ref={scrollRef}
        style={{
          display: "flex",
          gap,
          overflowX: "auto",
          scrollSnapType: "x mandatory",
          scrollPadding: "0 20px",
          padding: "0 20px",
          WebkitOverflowScrolling: "touch",
          scrollbarWidth: "none",
        }}
        className="hide-scrollbar">
        {trails.map((trail, i) => {
          const cardLeft = i * (cardWidth + gap) + 20 - scrollX;
          return (
            <Card
              key={trail.name + i}
              trail={trail}
              viewportWidth={viewportWidth}
              cardLeft={cardLeft}
              cardWidth={cardWidth}
              cardHeight={cardHeight}
              onSelect={onSelect}
            />
          );
        })}
      </div>
    </div>
  );
}

// Helper to rotate the array so each row shows a different starting order
const rotate = (arr, n) => [...arr.slice(n), ...arr.slice(0, n)];

