function ElevationProfile() {
  // Simple decorative elevation curve, purely visual mock
  const points = "0,60 20,55 40,45 55,48 70,20 85,28 100,5";
  return (
    <div
      style={{ background: "#16181c", borderRadius: 12, padding: "16px 12px" }}>
      <svg
        viewBox="0 0 100 60"
        preserveAspectRatio="none"
        style={{ width: "100%", height: 80 }}>
        <polyline
          points={points}
          fill="none"
          stroke="#4f9b6e"
          strokeWidth="2"
          vectorEffect="non-scaling-stroke"
        />
        <polygon
          points={`0,60 ${points} 100,60`}
          fill="#4f9b6e"
          opacity="0.15"
        />
      </svg>
    </div>
  );
}

