export default function ExploreTrailsPage() {
  const [view, setView] = useState("explore"); // "explore" | "detail" | "create"
  const [selectedTrail, setSelectedTrail] = useState(null);

  const easy = TRAILS.filter((t) => t.difficulty === "Easy");
  const moderate = TRAILS.filter((t) => t.difficulty === "Moderate");
  const hard = TRAILS.filter((t) => t.difficulty === "Hard");

  if (view === "detail" && selectedTrail) {
    return (
      <TrailDetailPage
        trail={selectedTrail}
        onBack={() => setView("explore")}
        onCreateRoute={(trail) => {
          setSelectedTrail(trail);
          setView("create");
        }}
      />
    );
  }

  if (view === "create") {
    return (
      <CreateRoutePage
        baseTrail={selectedTrail}
        onBack={() => setView(selectedTrail ? "detail" : "explore")}
      />
    );
  }

  const openTrail = (trail) => {
    setSelectedTrail(trail);
    setView("detail");
  };

  return (
    <div
      style={{
        background: "#0e0f12",
        minHeight: "100vh",
        padding: "32px 0 48px",
        fontFamily: "-apple-system, Inter, sans-serif",
        position: "relative",
      }}>
      <div style={{ padding: "0 20px", marginBottom: 24 }}>
        <h1 style={{ color: "#fff", fontSize: 26, fontWeight: 800, margin: 0 }}>
          Explore Trails
        </h1>
        <p style={{ color: "#8a8d96", fontSize: 14, marginTop: 4 }}>
          {TRAILS.length} trails near you
        </p>
      </div>

      <Row
        title="Featured this week"
        subtitle="Hand-picked trails to try"
        trails={rotate(TRAILS, 0)}
        cardWidth={170}
        cardHeight={210}
        onSelect={openTrail}
      />
      <Row
        title="Easy walks"
        subtitle="Good for a relaxed afternoon"
        trails={easy.concat(rotate(easy, 2))}
        onSelect={openTrail}
      />
      <Row
        title="Moderate hikes"
        subtitle="A bit more of a challenge"
        trails={moderate.concat(rotate(moderate, 2))}
        onSelect={openTrail}
      />
      <Row
        title="Hard climbs"
        subtitle="For experienced hikers"
        trails={hard.concat(rotate(hard, 1))}
        onSelect={openTrail}
      />
      <Row
        title="All trails"
        subtitle="Browse everything nearby"
        trails={rotate(TRAILS, 4)}
        onSelect={openTrail}
      />

      {/* Floating CTA to start a new route from scratch */}
      <button
        onClick={() => {
          setSelectedTrail(null);
          setView("create");
        }}
        style={{
          position: "fixed",
          bottom: 24,
          right: 20,
          padding: "14px 20px",
          borderRadius: 28,
          border: "none",
          background: "#4f9b6e",
          color: "#fff",
          fontSize: 14,
          fontWeight: 700,
          boxShadow: "0 8px 20px -6px rgba(79,155,110,0.6)",
          cursor: "pointer",
          display: "flex",
          alignItems: "center",
          gap: 6,
        }}>
        <span style={{ fontSize: 16 }}>+</span> Plan a route
      </button>

      <style>{`
        .hide-scrollbar::-webkit-scrollbar { display: none; }
      `}</style>
    </div>
  );
}
